import{_ as s,C as i,o as n,c as r,j as t,a as o,E as h,a5 as d}from"./chunks/framework.-jms6n7v.js";const w=JSON.parse('{"title":"Performance","description":"How fast DaruDB reads and writes next to the embedded databases each of its languages uses most, measured with the benchmark in the repository: the same…","frontmatter":{"title":"Performance","order":3,"aside":false,"pageClass":"performance-page","prev":{"text":"Comparison","link":"/compare"},"next":{"text":"Migration","link":"/migration/"}},"headers":[{"level":2,"title":"What is measured","slug":"what-is-measured","link":"#what-is-measured","children":[]},{"level":2,"title":"How it is kept fair","slug":"how-it-is-kept-fair","link":"#how-it-is-kept-fair","children":[]},{"level":2,"title":"Next to Realm","slug":"next-to-realm","link":"#next-to-realm","children":[]},{"level":2,"title":"Where DaruDB is behind, and why","slug":"where-darudb-is-behind-and-why","link":"#where-darudb-is-behind-and-why","children":[]},{"level":2,"title":"Run it yourself","slug":"run-it-yourself","link":"#run-it-yourself","children":[]}],"relativePath":"performance.md","filePath":"en/performance.md","lastUpdated":1791722537000}'),l={name:"performance.md"};function c(u,e,m,f,p,g){const a=i("PerformanceTable");return n(),r("div",null,[e[0]||(e[0]=t("h1",{id:"performance",tabindex:"-1"},[o("Performance "),t("a",{class:"header-anchor",href:"#performance","aria-label":'Permalink to "Performance"'},"​")],-1)),e[1]||(e[1]=t("p",null,"How fast DaruDB reads and writes next to the embedded databases each of its languages uses most, measured with the benchmark in the repository: the same objects and workloads in every database, at the same durability settings, on one machine.",-1)),e[2]||(e[2]=t("p",null,"The table follows the language chosen in the sidebar. The stores of one language ran on one machine one after another, so their times compare with each other; the tables of different languages come from different runs and do not.",-1)),h(a),e[3]||(e[3]=d(`<h2 id="what-is-measured" tabindex="-1">What is measured <a class="header-anchor" href="#what-is-measured" aria-label="Permalink to &quot;What is measured&quot;">​</a></h2><p>One collection of 100,000 objects, each with a name, an email under a unique index, an age under an index, a city and a score, both without an index. Every row times many operations and divides by their number:</p><table tabindex="0"><thead><tr><th>Workload</th><th>What it does</th></tr></thead><tbody><tr><td>Insert, one object per sync commit</td><td>500 commits of one object, each waiting for the disk</td></tr><tr><td>Insert, one object per deferred commit</td><td>10,000 commits of one object, each leaving the sync for later</td></tr><tr><td>Insert 100,000 objects in one transaction</td><td>Every object, the commit included</td></tr><tr><td>Get by primary key, random order</td><td>100,000 reads of one object</td></tr><tr><td>Get by a unique index, random order</td><td>20,000 reads of one object through the email</td></tr><tr><td>Query an indexed value, 1,250 objects</td><td>The objects of one age</td></tr><tr><td>Query an indexed range, sorted, first 20</td><td>The first 20 objects of five ages, sorted by age descending, then by key</td></tr><tr><td>Count through an index</td><td>The objects with an age of 40 or more</td></tr><tr><td>Query without an index, 1,000 objects</td><td>The objects of one city, ten times over</td></tr><tr><td>Query without an index, 1,000 objects, first run</td><td>The first of those ten</td></tr><tr><td>Top 10 by a field without an index</td><td>The 10 objects with the highest score, ten times over</td></tr><tr><td>Top 10 by a field without an index, first run</td><td>The first of those ten</td></tr><tr><td>Read and update 10,000 objects</td><td>Each read, given a new age and written back, in one transaction with its commit</td></tr><tr><td>Delete 10,000 objects</td><td>In one transaction with its commit</td></tr></tbody></table><p>The two queries without an index each have a row of their own for their first run, since DaruDB answers such a query faster once it has run: it remembers where the field it tests or sorts by lies in each record it read, and reads it there the next time. A query that an application runs once takes the time of the first run.</p><p>Every database is used the way an application in that language would use it. DaruDB runs through its public API with a schema, SQLite through SQL with prepared statements, and the key-value stores keep a record and the indexes an application would write for them. Every read is made into an object of the language with all its fields, and a query that runs many times is prepared once. An update sets the one field it changes where the language&#39;s DaruDB package can, as SQL sets one column: through Node.js, Python and Dart with <code>update</code>, where writing the whole object back would build it again in the language first, and through Rust by writing the typed struct back, which is faster there than an update whose changes name the field.</p><p>The Node.js and Dart tables also have Realm, for applications moving from it, though its vendor deprecated it in September 2024 and ended support in September 2025; the <a href="./migration/realm">migration guide</a> shows how to move the data. Realm assigns no keys, so the application gives each object the key the other stores assign. It has no unique index besides the primary key, so the email has a plain index, and its queries are strings it parses on every call, since it has no prepared queries. An update sets the one property.</p><h2 id="how-it-is-kept-fair" tabindex="-1">How it is kept fair <a class="header-anchor" href="#how-it-is-kept-fair" aria-label="Permalink to &quot;How it is kept fair&quot;">​</a></h2><ul><li><strong>The same durability.</strong> A sync commit waits until the disk has it: DaruDB&#39;s default commit, SQLite&#39;s write-ahead log with <code>synchronous = FULL</code>, LMDB&#39;s default commit, redb&#39;s <code>Durability::Immediate</code>, Hive&#39;s write followed by <code>flush</code>, and Realm&#39;s commit. A deferred commit returns before that: DaruDB&#39;s deferred commit, <code>synchronous = NORMAL</code>, LMDB&#39;s <code>NO_SYNC</code>, redb&#39;s <code>Durability::None</code> and Hive&#39;s write alone. Realm has no commit that leaves the sync for later, so its cell in that row is empty. redb&#39;s promises less than the others, since nothing it writes is durable until a later immediate commit.</li><li><strong>The same work.</strong> Every row hashes the keys and ages of what it found, in the order it found them, and a run in which two databases disagree fails rather than giving a time.</li><li><strong>A clean start.</strong> Each pass of each database runs in a process of its own, on new files, and the databases take turns in an order that changes every run. A time is the median of the runs.</li><li><strong>The same machine.</strong> The databases of one language run on one machine, one after another.</li></ul><p>The cache each database may use is left at its default, apart from SQLite&#39;s, which is raised to DaruDB&#39;s 32 MiB. A database that keeps every object in memory, as Hive does, reads without touching its file.</p><p>The tables come from the <code>run-benchmarks</code> workflow, which runs each language on a GitHub-hosted Linux runner of its own. Those runners mount their disk without write barriers, so a sync commit there waits for the file system&#39;s work but not for the disk&#39;s own cache. They also differ in processor and disk from one run to the next, and the commit rows move most with them: through Node.js, a deferred commit of one object took SQLite 68 µs and DaruDB 34 µs on the runner of one run, and 34 µs and 46 µs on that of the next. The next section says why. Compare a commit row&#39;s databases within one table only.</p><h2 id="next-to-realm" tabindex="-1">Next to Realm <a class="header-anchor" href="#next-to-realm" aria-label="Permalink to &quot;Next to Realm&quot;">​</a></h2><p>For an application moving from Realm, the Node.js and Dart tables are the ones to read; choose Node.js or Dart in the sidebar to see them. DaruDB is ahead of Realm in every row but the first run of the query of one city, a field without an index, and in Dart the update as well. Realm keeps each property&#39;s values together and reads only the city, and takes 0.72 times DaruDB&#39;s time on the first run in Node.js and 0.93 times in Dart; over ten runs it takes 1.07 and 1.19 times, since from the second run on DaruDB reads the city where the first found it in each record. In Node.js and in Dart, Realm takes 2.3 and 2.2 times as long for a sync commit and has no deferred one, 6.6 and 4.3 times as long to insert 100,000 objects in one transaction, and 6.2 and 2.3 times to delete 10,000. It takes 3.8 and 3.1 times as long to read by key, and 13 and 10 times through the email, since it parses a query string on every call and has no unique index besides the primary key. It takes 4.6 and 5.0 times as long for the objects of one age, 114 and 103 times for the first 20 of five ages, since it sorts every object of the five ages before it takes the first 20, and 2.6 to 3.8 times for the ten objects with the highest score. An update sets one field in both, and takes Realm 1.14 times DaruDB&#39;s time in Node.js and 0.76 times in Dart.</p><h2 id="where-darudb-is-behind-and-why" tabindex="-1">Where DaruDB is behind, and why <a class="header-anchor" href="#where-darudb-is-behind-and-why" aria-label="Permalink to &quot;Where DaruDB is behind, and why&quot;">​</a></h2><p>In this run Rust and Python ran on runners with AMD EPYC 9V45 processors, and Node.js and Dart on ones with an AMD EPYC 7763. DaruDB is ahead of every other database in most rows in Node.js and Python, and in Python ahead of SQLite in every row but one. In Dart it is ahead in the insert of 100,000 objects in one transaction, the reads and queries through an index and the count; Hive, which keeps every object in memory, is ahead in the read by key and the queries without an index, Realm in the update, and SQLite in the commits of one object and the delete. In Rust, LMDB is ahead in the deferred commit, the reads and the queries but the count, and redb and SQLite in the queries through the age index and the first run of those without one. These are the rows where DaruDB is not ahead, with what makes each slower:</p><ul><li><strong>A deferred commit of one object.</strong> LMDB is ahead in every language it runs in, taking 0.37 to 0.52 times DaruDB&#39;s time, redb in Rust, taking 0.73 times, and SQLite in Node.js and Dart, taking 0.75 and 0.81 times. On Linux, about half of DaruDB&#39;s commit is spent in the kernel: it makes about fourteen system calls, ten writes for the eleven or so pages it writes and four to take and release the writer lock and to check for other writers and readers, since processes coordinate through file locks alone. LMDB makes seven writes and coordinates processes through a mutex in shared memory, which DaruDB rejects: a process that dies holding one can leave the others stuck. SQLite&#39;s deferred commits are not all of its work: it syncs its log and its file at each checkpoint of the log, every thousand pages, and on most runners its deferred commits spent two thirds of their time or more waiting for those syncs. The EPYC 7763 runners finish them sooner, and their processor, the oldest of the runner kinds, is the slowest at DaruDB&#39;s commit, which waits for nothing. In Rust and Python, on EPYC 9V45 runners, DaruDB&#39;s deferred commit took about half of SQLite&#39;s time or less.</li><li><strong>Sync commits</strong> move from runner to runner more than any other row. In this run SQLite takes 0.87 times DaruDB&#39;s time in Node.js and 0.84 times in Dart, on EPYC 7763 runners, while in Rust and Python, on EPYC 9V45 runners, DaruDB is ahead of every other database. On the runners, a sync commit is mostly the file system&#39;s work. DaruDB writes a commit&#39;s pages where the free pages are, scattered over the file, where SQLite appends its pages to its log, and on the EPYC 7763 runners syncing twelve pages written scattered over a file took three times as long as syncing the same twelve written in one run, in a probe of the disk alone.</li><li><strong>Reads and queries through an index, in Rust.</strong> LMDB finds an object by its key in 0.72 times DaruDB&#39;s time and redb in 0.88 times, LMDB finds one by its email in 0.74 times, and LMDB, redb and SQLite run the queries through the age index in 0.52 to 0.88 times. A DaruDB lookup finds each page below the root in its page cache, under a lock and with a reference count, which takes a larger share of a lookup on these x86 processors than on Apple&#39;s, then searches the node comparing keys as bytes, and decodes the record, which tags each field with an id, into the struct. LMDB reads its file through a memory map, with no cache to look in, redb compares its primary keys as integers, and both read the record written by hand for them, with its fields at fixed places. DaruDB does not map its file, because another process can change mapped bytes under a reader, and a mapping does not mix with encryption. The sorted range costs more besides: it sorts by age descending and then by key, so DaruDB walks the age index backwards and holds back the objects of each age to give them in key order, where the loop written for the key-value stores asks for each age in turn. On an Apple M1 Max, DaruDB was ahead of LMDB in these rows but the sorted range.</li><li><strong>A read by key in Dart</strong>, where Hive takes 0.85 times DaruDB&#39;s time. Hive keeps every object of a box in memory and gives the one it holds, where DaruDB finds the record in its tree, through the page cache, and makes the object from it.</li><li><strong>Queries without an index.</strong> LMDB in Rust scans 2.4 to 6.9 times as fast, Hive in Dart 1.2 to 2.5 times, and Realm finds the objects of one city faster on the first run, in Node.js and in Dart. SQLite and redb are ahead on the first run alone: SQLite takes 0.80 to 0.96 times DaruDB&#39;s time in Rust, Node.js and Dart, and in one of the two queries in Python, and redb 0.93 and 0.94 times in Rust. Over ten runs DaruDB is ahead of both, which take 1.20 to 1.58 times its time, and of Realm, which takes 1.07 to 3.8 times. The record written by hand for the key-value stores keeps the age and the score at fixed places, so a scan reads those bytes and decodes only what it returns; Realm keeps each property&#39;s values together, so a scan reads only the city; and SQLite&#39;s record lists the types of its columns at its start, so finding one column adds up the sizes before it without reading them. A DaruDB record tags each field with an id and a type, which makes renaming a field free and lets the engine check what it reads from a file it does not trust, so a first scan steps over the fields before the one it tests in each record. It remembers where it found the field, and the runs after the first read it there.</li><li><strong>An update in Dart</strong>, where Realm takes 0.76 times DaruDB&#39;s time, and 1.14 times in Node.js. Realm keeps each property&#39;s values together, so setting the age changes that value alone, where DaruDB writes the object&#39;s record again with the new age.</li><li><strong>A delete of 10,000 objects in Dart</strong>, where SQLite takes 0.91 times DaruDB&#39;s time; DaruDB is ahead in the other languages. The delete is one transaction whose commit syncs, and DaruDB&#39;s commit of many scattered changes writes its pages where earlier commits freed pages, so it makes many more write calls, and on the EPYC 7763 runners syncing pages scattered over the file takes longer than syncing pages written in one run, as the sync commits show.</li><li><strong>A lookup through a unique index in Node.js</strong>, where SQLite takes 0.90 times DaruDB&#39;s time: two lookups make it, the email&#39;s entry in the index and then the object by its key, and making the object from its record in JavaScript takes a fifth of it.</li></ul><h2 id="run-it-yourself" tabindex="-1">Run it yourself <a class="header-anchor" href="#run-it-yourself" aria-label="Permalink to &quot;Run it yourself&quot;">​</a></h2><p>The harness is in <a href="https://github.com/jooy2/darudb/tree/main/bench" target="_blank" rel="noreferrer"><code>bench/</code></a> of the repository, with a README that lists every setting. The <code>run-benchmarks</code> workflow runs it on GitHub-hosted runners and opens a pull request with the results for this page.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bench/rust</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../..</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bench/run.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rust</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --runs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 9</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bench/results/rust.json</span></span></code></pre></div>`,18))])}const y=s(l,[["render",c]]);export{w as __pageData,y as default};
